def merge(values):
    if not isinstance(values, list):
        raise ValueError("values must be a list")

    for interval in values:
        if not isinstance(interval, tuple) or len(interval) != 2:
            raise ValueError("each range must be a tuple of two integers")
        start, end = interval
        if type(start) is not int or type(end) is not int:
            raise ValueError("range endpoints must be integers")
        if start > end:
            raise ValueError("range start must not exceed its end")

    merged = []
    for start, end in sorted(values, key=lambda interval: interval[0]):
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged

